<script setup lang="ts">definePageMeta({layout:"auth"});const{tr}=useAppPreferences(),route=useRoute();const form=reactive({password:"",confirmPassword:""}),busy=ref(false),done=ref(false),error=ref("");async function submit(){busy.value=true;error.value="";try{await $fetch("/api/auth/reset-password",{method:"POST",body:{token:String(route.query.token||""),...form}});done.value=true}catch(e:any){error.value=e.data?.statusMessage||tr("تغییر رمز ناموفق بود.","Could not reset password.")}finally{busy.value=false}}</script><template><form @submit.prevent="submit"><h1 class="text-3xl font-black">{{tr('انتخاب رمز جدید','Choose a new password')}}</h1><p class="muted mb-7 mt-3">{{tr('رمز جدید باید حداقل ۸ نویسه باشد.','Your new password must be at least 8 characters.')}}</p><div v-if="error" class="mb-4 rounded-xl bg-red-50 p-4 text-sm font-bold text-red-700">{{error}}</div><div v-if="done" class="rounded-xl bg-emerald-50 p-4 text-sm font-bold text-emerald-700">{{tr('رمز عبور تغییر کرد. اکنون وارد حساب شوید.','Password changed. You can now sign in.')}}<NuxtLink to="/login" class="btn btn-primary mt-4 w-full">{{tr('ورود','Sign in')}}</NuxtLink></div><template v-else><input v-model="form.password" class="input mb-4" type="password" required minlength="8" :placeholder="tr('رمز جدید','New password')"><input v-model="form.confirmPassword" class="input" type="password" required minlength="8" :placeholder="tr('تکرار رمز جدید','Confirm password')"><button class="btn btn-primary mt-4 w-full" :disabled="busy||!route.query.token">{{busy?tr('در حال ذخیره...','Saving...'):tr('تغییر رمز عبور','Change password')}}</button></template></form></template>
